// searchSavedPlaces - deterministic search over the user's saved places sheet.
const rows = $('Get row(s) in sheet').all().map(item => item.json);

let params = {};
if (typeof query === 'object' && query !== null) {
  params = query;
} else if (typeof query === 'string' && query.trim().startsWith('{')) {
  try { params = JSON.parse(query); } catch (e) { params = {}; }
}

const norm = (v) => (v === undefined || v === null ? '' : v.toString()).toLowerCase().trim();
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const isSet = (v) => v !== undefined && v !== null && v !== '';
const wordHit = (hay, term) => new RegExp('\\b' + esc(term) + '\\b').test(hay);

const KNOWN = ['location', 'city', 'region', 'area', 'cuisine', 'category', 'type', 'keyword', 'minRating', 'maxPrice', 'visited'];
const ignoredParams = Object.keys(params).filter(k => KNOWN.indexOf(k) === -1 && isSet(params[k]));

const locationInput = params.location || params.city || params.region || params.area || '';
const categoryInput = params.cuisine || params.category || params.type || '';
const keywordInput = params.keyword || '';

// Split ONLY on real separators - never on bare spaces, so "ice cream" stays one phrase.
const splitTerms = (s) => norm(s)
  .split(/\s*(?:,|\/|\||\+|&|\bor\b|\band\b)\s*/)
  .map(t => t.trim())
  .filter(Boolean);

// One-directional synonym map: a query term expands to these match words.
const CATEGORY_SYNONYMS = {
  'pub': ['pub', 'bar', 'tavern', 'saloon', 'brewery', 'brewpub', 'taproom', 'beer', 'lounge', 'cocktail', 'speakeasy', 'rooftop'],
  'bar': ['bar', 'pub', 'tavern', 'saloon', 'lounge', 'cocktail', 'speakeasy', 'taproom', 'brewery', 'brewpub', 'rooftop'],
  'tavern': ['tavern', 'pub', 'bar', 'saloon'],
  'brewery': ['brewery', 'brewpub', 'taproom', 'beer', 'pub'],
  'beer': ['beer', 'brewery', 'brewpub', 'taproom', 'pub', 'bar'],
  'cocktail': ['cocktail', 'bar', 'speakeasy', 'lounge'],
  'drinks': ['bar', 'pub', 'cocktail', 'lounge', 'brewery'],
  'nightlife': ['bar', 'pub', 'cocktail', 'lounge', 'speakeasy'],
  'coffee': ['coffee', 'cafe', 'espresso', 'roaster'],
  'cafe': ['cafe', 'coffee', 'espresso', 'roaster'],
  'tea': ['tea', 'matcha', 'boba', 'bubble tea'],
  'boba': ['boba', 'bubble tea', 'tea'],
  'ice cream': ['ice cream', 'gelato', 'creamery', 'frozen yogurt', 'froyo', 'soft serve'],
  'gelato': ['gelato', 'ice cream', 'creamery'],
  'dessert': ['dessert', 'ice cream', 'gelato', 'creamery', 'bakery', 'patisserie', 'pastry', 'cake', 'donut', 'doughnut', 'sweets', 'candy', 'chocolate'],
  'sweets': ['sweets', 'dessert', 'candy', 'chocolate', 'bakery'],
  'bakery': ['bakery', 'patisserie', 'pastry', 'bread', 'croissant', 'cake'],
  'pastry': ['pastry', 'patisserie', 'bakery', 'croissant'],
  'donut': ['donut', 'doughnut'],
  'brunch': ['brunch', 'breakfast', 'diner', 'pancake', 'waffle', 'bagel'],
  'breakfast': ['breakfast', 'brunch', 'diner', 'pancake', 'waffle', 'bagel'],
  'pizza': ['pizza', 'pizzeria'],
  'burger': ['burger', 'burgers', 'cheeseburger', 'smash burger'],
  'ramen': ['ramen', 'noodle', 'udon', 'soba'],
  'noodles': ['noodle', 'ramen', 'udon', 'soba', 'pho'],
  'indian': ['indian', 'south indian', 'north indian', 'biryani', 'curry'],
  'mexican': ['mexican', 'taco', 'taqueria', 'burrito'],
  'chinese': ['chinese', 'dim sum', 'sichuan', 'szechuan', 'cantonese'],
  'japanese': ['japanese', 'sushi', 'izakaya', 'ramen'],
  'italian': ['italian', 'pasta', 'trattoria', 'pizzeria']
};

const LOCATION_ALIASES = {
  'bay area': ['san francisco', 'south bay', 'peninsula', 'east bay', 'north bay'],
  'sf': ['san francisco'],
  'the city': ['san francisco'],
  'south bay': ['south bay', 'peninsula'],
  'silicon valley': ['south bay', 'peninsula'],
  'peninsula': ['peninsula', 'south bay'],
  'tahoe': ['lake tahoe'],
  'la': ['los angeles'],
  'socal': ['los angeles'],
  'nyc': ['new york'],
  'monterey': ['monterey', 'big sur'],
  'wine country': ['north bay', 'napa', 'sonoma']
};

const expandCategory = (term) => {
  if (term.length < 3) return [term];
  if (CATEGORY_SYNONYMS[term]) return CATEGORY_SYNONYMS[term];
  const key = Object.keys(CATEGORY_SYNONYMS).find(k => wordHit(term, k));
  if (key) {
    const out = [term];
    CATEGORY_SYNONYMS[key].forEach(w => { if (out.indexOf(w) === -1) out.push(w); });
    return out;
  }
  return [term];
};
const expandLocation = (term) => {
  const out = [term];
  const al = LOCATION_ALIASES[term];
  if (al) al.forEach(w => { if (out.indexOf(w) === -1) out.push(w); });
  return out;
};

const locTerms = splitTerms(locationInput).reduce((a, t) => a.concat(expandLocation(t)), []);
const catTerms = splitTerms(categoryInput).reduce((a, t) => a.concat(expandCategory(t)), []);
const kwTerms = splitTerms(keywordInput);

const locHay = (r) => norm(r.City) + ' | ' + norm(r.Region);
const catHay = (r) => norm(r.Category) + ' | ' + norm(r.Type) + ' | ' + norm(r.Cuisine);
const nameHay = (r) => catHay(r) + ' | ' + norm(r['Place Name']);
const kwHay = (r) => nameHay(r) + ' | ' + norm(r.Notes) + ' | ' + locHay(r) + ' | ' + norm(r.Address);

const fLoc = (r) => !locTerms.length || locTerms.some(t => locHay(r).indexOf(t) !== -1);
const fCatStrict = (r) => !catTerms.length || catTerms.some(t => wordHit(catHay(r), t));
const fCatLoose = (r) => !catTerms.length || catTerms.some(t => catHay(r).indexOf(t) !== -1);
const fCatName = (r) => !catTerms.length || catTerms.some(t => nameHay(r).indexOf(t) !== -1);
const fKw = (r) => !kwTerms.length || kwTerms.some(t => kwHay(r).indexOf(t) !== -1);

const minRating = isSet(params.minRating) ? parseFloat(params.minRating) : NaN;
const fRating = (r) => isNaN(minRating) || minRating <= 0 || parseFloat(r.Rating) >= minRating;

const budgetCap = (() => {
  const t = norm(params.maxPrice);
  if (!t) return null;
  const nums = t.match(/\d+/g);
  if (nums) return Math.max.apply(null, nums.map(Number));
  if (/cheap|budget|inexpensive|affordable/.test(t)) return 20;
  if (/moderate|mid/.test(t)) return 40;
  if (/expensive|upscale|fancy|splurge|high end/.test(t)) return 100000;
  return null;
})();
const rowPriceMax = (r) => { const n = String(r['Price Range'] || '').match(/\d+/g); return n ? Math.max.apply(null, n.map(Number)) : null; };
const fPrice = (r) => budgetCap === null || rowPriceMax(r) === null || rowPriceMax(r) <= budgetCap;

const fVisited = (r) => {
  if (!isSet(params.visited)) return true;
  const want = params.visited === true || norm(params.visited) === 'true' || norm(params.visited) === 'yes';
  // Tolerant of stray formatting written by earlier updates, e.g. ["Yes"]
  const v = norm(r['Visited?']).replace(/[^a-z]/g, '');
  const is = v === 'true' || v === 'yes' || v === 'y' || v === 'visited' || v === 'done';
  return is === want;
};

const apply = (catFn) => rows.filter(r => fLoc(r) && catFn(r) && fKw(r) && fRating(r) && fPrice(r) && fVisited(r));

let matched = apply(fCatStrict);
let matchMode = 'exact';
if (!matched.length && catTerms.length) { matched = apply(fCatLoose); matchMode = 'loose'; }
if (!matched.length && catTerms.length) { matched = apply(fCatName); matchMode = 'nameMatch'; }

matched.sort((a, b) =>
  ((parseFloat(b.Rating) || 0) - (parseFloat(a.Rating) || 0)) ||
  ((parseInt(b.Reviews, 10) || 0) - (parseInt(a.Reviews, 10) || 0))
);

const LIMIT = 25;
const output = matched.slice(0, LIMIT).map(r => ({
  name: r['Place Name'],
  category: r.Category || r.Type,
  rating: r.Rating,
  reviews: r.Reviews,
  priceRange: r['Price Range'],
  visited: r['Visited?'],
  city: r.City,
  region: r.Region,
  address: r.Address,
  notes: r.Notes
}));

const result = {
  matchCount: matched.length,
  returned: output.length,
  truncated: matched.length > output.length,
  totalSaved: rows.length,
  matchMode: matchMode,
  filtersApplied: {
    location: locTerms,
    category: catTerms,
    keyword: kwTerms,
    minRating: isNaN(minRating) ? null : minRating,
    maxPriceCap: budgetCap,
    visited: isSet(params.visited) ? params.visited : null
  },
  results: output
};

if (ignoredParams.length) {
  result.ignoredParams = ignoredParams;
  result.warning = 'Unsupported parameters were ignored: ' + ignoredParams.join(', ') + '. Supported: location, cuisine, keyword, minRating, maxPrice, visited.';
}

if (!matched.length) {
  const inLoc = rows.filter(r => fLoc(r));
  const inCat = rows.filter(r => fCatName(r));
  const catCount = {};
  inLoc.forEach(r => { const c = r.Category || r.Type || 'Unknown'; catCount[c] = (catCount[c] || 0) + 1; });
  const topCats = Object.keys(catCount).sort((a, b) => catCount[b] - catCount[a]).slice(0, 12).map(c => c + ' (' + catCount[c] + ')');
  const regions = {};
  rows.forEach(r => { const g = r.Region || 'Unknown'; regions[g] = (regions[g] || 0) + 1; });
  const citiesForCat = Array.from(new Set(inCat.map(r => r.City).filter(Boolean))).slice(0, 12);

  result.diagnostics = {
    savedInThatLocation: locTerms.length ? inLoc.length : null,
    savedInThatCategoryAnywhere: catTerms.length ? inCat.length : null,
    categoriesSavedInThatLocation: locTerms.length ? topCats : null,
    citiesWhereThatCategoryIsSaved: catTerms.length ? citiesForCat : null,
    regionsAvailable: regions
  };
  result.hint = 'Nothing matched ALL filters. Read diagnostics before telling the user they have nothing saved. If savedInThatLocation > 0 they DO have places there, just not this category - say which categories they do have there. If savedInThatCategoryAnywhere > 0 they have this category saved elsewhere - name those cities. Only say the list has nothing when both counts are 0.';
}

return JSON.stringify(result);

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "location": {
      "type": "string",
      "description": "City, area or region to filter by. Accepts a city (San Francisco, Santa Clara, Berkeley) OR a region - both the City and Region columns are searched. Valid regions: San Francisco, South Bay / Peninsula, East Bay, North Bay, Santa Cruz, Monterey Bay & Big Sur, Lake Tahoe, Los Angeles, New York City, Central Valley / Northern CA. Pass the user's own wording (South Bay, Bay Area, Silicon Valley, Peninsula, Tahoe, LA, NYC all work). Omit if the user did not mention a place."
    },
    "cuisine": {
      "type": "string",
      "description": "Cuisine, category or venue type in the user's own words, e.g. Indian, pizza, cafe, pub, ice cream, bakery. Close synonyms are expanded automatically (pub also finds bars, taprooms, breweries and lounges; coffee also finds cafes). Keep multi-word phrases intact - send 'ice cream', not 'ice'. Omit if the user did not name a kind of place."
    },
    "keyword": {
      "type": "string",
      "description": "Free-text term matched against place name, notes, address, city and category. Use for a specific place name or an unusual descriptor. Omit for ordinary category searches."
    },
    "minRating": {
      "type": "number",
      "description": "Minimum star rating, e.g. 4. Omit unless the user asked for highly-rated or best places."
    },
    "maxPrice": {
      "type": "string",
      "description": "Budget cap, e.g. cheap, under $30, $20-30. Omit unless the user mentioned budget."
    },
    "visited": {
      "type": "boolean",
      "description": "true = only places already visited, false = only not-yet-visited. Omit unless the user asked about visited status."
    }
  }
}

