const item = $input.first().json;

// If the AI Agent failed (On Error: continue using regular output) it passes the
// error through instead of an answer - reply with a friendly note, never silence.
if (item.error && !item.output && !item.text) {
  const raw = typeof item.error === 'string' ? item.error : (item.error.message || item.error.description || '');
  const busy = /503|high demand|unavailable|overload|rate limit|429|timeout/i.test(raw);
  const replyText = busy
    ? "Ugh - my brain's servers are slammed right now. Give me a minute and ask me again?"
    : "Something went wrong on my end just now. Mind trying that again?";
  return [{ json: { replyText, failed: true, reason: String(raw).slice(0, 300) } }];
}

let replyText = (item.output || item.text || '').toString().trim();

const MAX_LEN = 1500;
if (replyText.length > MAX_LEN) {
  replyText = replyText.slice(0, MAX_LEN - 40).trim() + '...\n\n(trimmed for length - ask me for more!)';
}

if (!replyText) {
  replyText = "Hmm, I'm drawing a blank on that one - mind rephrasing?";
}

return [{ json: { replyText } }];

const rows = $('Get row(s) in sheet').all().map(item => item.json);

let params = {};
if (typeof query === 'object' && query !== null) {
    params = query;
} else if (typeof query === 'string' && query.trim().startsWith('{')) {
    try { params = JSON.parse(query); } catch (e) { params = {}; }
} else if (typeof query === 'string') {
    params = { placeName: query };
}

const norm = (v) => (v === undefined || v === null ? '' : v.toString()).toLowerCase().trim();

const nameQ = norm(params.placeName);
const cityQ = norm(params.city);

let matches = rows.filter(r => {
    const name = norm(r['Place Name']);
    if (!nameQ) return false;
    const nameMatches = name.includes(nameQ) || nameQ.includes(name);
    if (!nameMatches) return false;
    if (cityQ) {
          return norm(r.City).includes(cityQ);
    }
    return true;
});

const output = matches.map(r => ({
    row_number: r.row_number,
    '#': r['#'],
    name: r['Place Name'],
    category: r.Category,
    city: r.City,
    address: r.Address,
    visited: r['Visited?'],
    notes: r.Notes
}));

return JSON.stringify({ matchCount: output.length, matches: output });

parameters.inputSchema:
{
    "type": "object",
    "properties": {
          "placeName": {
                  "type": "string",
                  "description": "The name (or partial name) of the place to find, e.g. 'Pint of Joy' or 'Cobi's'"
          },
          "city": {
                  "type": "string",
                  "description": "Optional city to narrow the match if multiple places share a similar name, e.g. 'Berkeley, CA'"
          }
    },
    "required": ["placeName"]
}
